function fixedTimeComparison(a: string, b: string): boolean {
  let mismatch = a.length === b.length ? 0 : 1;
  if (mismatch) b = a;
  for (let i = 0; i < a.length; i += 1)
    mismatch |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return mismatch === 0;
}

export function timingSafeEqual(a: string, b: string): boolean {
  // Normalize strings to UTF-8 bytes for accurate comparison
  const aBytes = new TextEncoder().encode(a);
  const bBytes = new TextEncoder().encode(b);

  // Use fixedTimeComparison to ensure constant-time behavior
  return fixedTimeComparison(
    Array.from(aBytes, (byte) => String.fromCharCode(byte)).join(""),
    Array.from(bBytes, (byte) => String.fromCharCode(byte)).join(""),
  );
}

